#!/usr/bin/env bash
# ODEME_VADELERI deploy — server endpoint (/api/bi/odeme-vadeleri) + mobil kokpit vade bölümü.
# Rule 5: docker build -t krb-assessment:secure . && compose up --force-recreate. Idempotent.
set -e
cd /opt/krb-assessment

# LIVE saha.js: shells/saha.js (backups/ ve node_modules HARİÇ)
if [ -f shells/saha.js ]; then
  SAHA=shells/saha.js
else
  SAHA=$(find . -maxdepth 3 -name saha.js -not -path '*/backups/*' -not -path '*/node_modules/*' | head -1)
fi
if [ -z "$SAHA" ] || [ ! -f "$SAHA" ]; then echo "HATA: canlı saha.js bulunamadı"; exit 1; fi
echo "saha.js -> $SAHA"

cp server_container.mjs server_container.mjs.bak.$(date +%s)
cp "$SAHA" "$SAHA.bak.$(date +%s)"

echo "== apply server endpoint patch =="
printf '%s' '' | base64 -d > odemevade_ep.py
python3 odemevade_ep.py

echo "== apply mobile chart patch ($SAHA) =="
printf '%s' '' | base64 -d > ovmobil.py
SDIR=$(dirname "$SAHA")
cp ovmobil.py "$SDIR/ovmobil.py"
( cd "$SDIR" && python3 ovmobil.py )
rm -f "$SDIR/ovmobil.py"

echo "== syntax check =="
node --check server_container.mjs && echo "SERVER_OK"
node --check "$SAHA" && echo "SAHA_OK"

echo "== docker build =="
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment

echo "== verify (beklenen: server=1, saha=2) =="
sleep 4
docker exec krb-assessment grep -c ODEME_VADELERI_V1 /app/server_container.mjs || true
docker exec krb-assessment grep -c ODEME_VADELERI_MOBIL_V1 /app/shells/saha.js || true
echo "== DONE =="
